def priority(item: float, bins: np.ndarray) -> np.ndarray:
    residual_capacity = bins - item
    valid_mask = residual_capacity > 0
    inverse_capacity = 1 / residual_capacity
    inverse_capacity[~valid_mask] = 0
    weighted_inverse = inverse_capacity * valid_mask
    weighted_inverse_sum = np.sum(weighted_inverse)
    if weighted_inverse_sum == 0:
