def priority(item: float, bins: np.ndarray) -> np.ndarray:
    bins = np.clip(bins, a_min=item, a_max=None)
    bins_ratio = bins / item
    term1 = np.exp(-8 * (bins_ratio - 1) ** 2)
    term2 = (bins_ratio >= 0.75)
    term3 = 1 + np.sin(np.pi * bins_ratio) - 0.7 * np.sqrt(bins_ratio)
    return np.maximum(
        0,
        term1 * term2 * term3
    )

