def priority(item: float, bins: np.ndarray) -> np.ndarray:
    diff = bins - item
    log_term = np.log(bins + 10 * np.finfo(float).eps)
    score = (diff * log_term ** 0.5).clip(0, item)
    return -score ** 1.5 * (1 + np.sin(np.pi * diff / item))

